const assetPathPrefix = "https://www.figma.com/api/mcp/asset/65631813-bea9-40ac-bb74-c573a09fdfad";
const imgAuthorPortrait = `${assetPathPrefix}/90b4a.png`;
const imgBookArtwork = `${assetPathPrefix}/356ef.png`;
const imgBookArtwork1 = `${assetPathPrefix}/8a45d.png`;
const imgBookArtwork2 = `${assetPathPrefix}/41d67.png`;

type CastleHomePromoProps = {
  className?: string;
  slide?: "Exclusive" | "Subscription";
};

function CastleHomePromo({ className, slide = "Exclusive" }: CastleHomePromoProps) {
  const isExclusive = slide === "Exclusive";
  const isSubscription = slide === "Subscription";
  return (
    <div className={className || "bg-[var(--castle-color-action-tint,rgba(74,143,255,0.08))] content-stretch flex flex-col gap-[12px] h-[252px] items-center justify-center p-[20px] relative rounded-[var(--castle-dimension-24,24px)] w-[358px]"} id={isSubscription ? "node-124_377" : "node-124_376"}>
      <div className="content-stretch flex gap-[var(--castle-dimension-12,12px)] h-[192px] items-center overflow-clip relative shrink-0 w-[318px]" id={isSubscription ? "node-124_392" : "node-124_380"} data-name="Promo content">
        <div className="[word-break:break-word] content-stretch flex flex-col gap-[var(--castle-dimension-12,12px)] items-start overflow-clip relative shrink-0 w-[190px]" id={isSubscription ? "node-124_393" : "node-124_381"} data-name="Copy">
          <div className="font-['Manrope:SemiBold'] font-semibold leading-[0] relative shrink-0 text-[20px] text-[color:var(--castle-color-text-primary,#101012)] tracking-[-0.2px] w-full" id={isSubscription ? "node-124_394" : "node-124_382"}>
            <p className="leading-[26px] mb-0">{isSubscription ? "Читайте больше" : "«Файл надежды»"}</p>
            <p className="leading-[26px]">{isSubscription ? "с подпиской" : "только у нас"}</p>
          </div>
          <div className="font-['Manrope:Regular'] font-normal leading-[0] relative shrink-0 text-[14px] text-[color:var(--castle-color-text-secondary,rgba(60,60,67,0.72))] w-full" id={isSubscription ? "node-124_395" : "node-124_383"}>
            <p className="leading-[20px] mb-0">{isSubscription ? "Большой книжный каталог" : "История про любовь,"}</p>
            <p className="leading-[20px]">{isSubscription ? "в одном приложении" : "смерть и робота"}</p>
          </div>
          <p className="font-['Manrope:Regular'] font-normal leading-[20px] relative shrink-0 text-[14px] text-[color:var(--castle-color-action-accent,#4a8fff)] w-full" id={isSubscription ? "node-124_396" : "node-124_384"}>
            {isSubscription ? "О подписке" : "Подробнее"}
          </p>
        </div>
        <div className="h-[168px] relative shrink-0 w-[116px]" id={isSubscription ? "node-124_397" : "node-124_385"} data-name="Artwork">
          {isExclusive && (
            <div className="absolute h-[132px] left-0 rounded-[16px] top-0 w-[116px]" data-node-id="124:386" data-name="Author portrait">
              <img alt="" className="absolute inset-0 max-w-none object-cover pointer-events-none rounded-[16px] size-full" src={imgAuthorPortrait} />
            </div>
          )}
          <div className={`absolute ${isSubscription ? "h-[112px] left-0 rounded-[6px] top-[8px] w-[76px]" : "h-[87px] left-[-8px] rounded-[4px] top-[78px] w-[58px]"}`} id={isSubscription ? "node-124_398" : "node-124_387"} data-name="Book artwork">
            <img alt="" className={`absolute inset-0 max-w-none object-contain pointer-events-none size-full ${isSubscription ? "rounded-[6px]" : "rounded-[4px]"}`} src={isSubscription ? imgBookArtwork1 : imgBookArtwork} />
          </div>
          {isSubscription && (
            <div className="absolute h-[112px] left-[40px] rounded-[6px] top-[54px] w-[76px]" data-node-id="124:399" data-name="Book artwork">
              <img alt="" className="absolute inset-0 max-w-none object-contain pointer-events-none rounded-[6px] size-full" src={imgBookArtwork2} />
            </div>
          )}
        </div>
      </div>
      <div className="content-stretch flex gap-[var(--castle-dimension-8,8px)] h-[8px] items-start justify-center overflow-clip relative shrink-0 w-[318px]" id={isSubscription ? "node-124_400" : "node-124_388"} data-name="Carousel pagination">
        {isExclusive && (
          <>
            <div className="bg-[var(--castle-color-action-accent,#4a8fff)] h-[8px] relative rounded-[4px] shrink-0 w-[24px]" data-node-id="124:389" data-name="Slide / Exclusive" />
            <button className="bg-[var(--castle-color-border-default,rgba(120,120,128,0.16))] block cursor-pointer relative rounded-[4px] shrink-0 size-[8px]" data-node-id="124:390" data-name="Slide / Subscription" />
            <button className="bg-[var(--castle-color-border-default,rgba(120,120,128,0.16))] block cursor-pointer relative rounded-[4px] shrink-0 size-[8px]" data-node-id="124:391" data-name="Slide / Formats" />
          </>
        )}
        {isSubscription && (
          <>
            <button className="bg-[var(--castle-color-border-default,rgba(120,120,128,0.16))] block cursor-pointer relative rounded-[4px] shrink-0 size-[8px]" data-node-id="124:401" data-name="Slide / Exclusive" />
            <div className="bg-[var(--castle-color-action-accent,#4a8fff)] h-[8px] relative rounded-[4px] shrink-0 w-[24px]" data-node-id="124:402" data-name="Slide / Subscription" />
            <button className="bg-[var(--castle-color-border-default,rgba(120,120,128,0.16))] block cursor-pointer relative rounded-[4px] shrink-0 size-[8px]" data-node-id="124:403" data-name="Slide / Formats" />
          </>
        )}
      </div>
    </div>
  );
}
